import json
from pathlib import Path

import numpy as np
import pandas as pd
from scipy.optimize import linprog
from scipy.sparse import eye, hstack


def fit_wealth_quantile(df: pd.DataFrame, q: float, year: int = 1996) -> dict:
    """Linear quantile regression of composite_wealth_<year> on race, sex and
    ever_jailed at quantile q.

    Returns {"coef": {"intercept", "black", "hispanic", "male", "ever_jailed"}, "n"}.
    """
    if not 0 < q < 1:
        raise ValueError("q must be strictly between 0 and 1")

    outcome = f"composite_wealth_{year}"
    y = df[outcome].to_numpy(dtype=float)
    n = len(df)

    # White and female are the reference categories.  The LP variables are
    # [beta, positive residuals, negative residuals], where
    # y - X beta = positive residual - negative residual.
    race = df["race"].astype(str)
    sex = df["sex"].astype(str)
    X = np.column_stack(
        [
            np.ones(n),
            (race == "black").to_numpy(dtype=float),
            (race == "hipanic").to_numpy(dtype=float),
            (sex == "male").to_numpy(dtype=float),
            df["ever_jailed"].to_numpy(dtype=float),
        ]
    )

    # Sparse construction is important: the two residual blocks contribute
    # only 2*n nonzero entries to the equality constraint.
    constraints = hstack([X, eye(n, format="csr"), -eye(n, format="csr")], format="csr")
    objective = np.concatenate([np.zeros(5), np.full(n, q), np.full(n, 1.0 - q)])
    result = linprog(
        objective,
        A_eq=constraints,
        b_eq=y,
        bounds=[(None, None)] * 5 + [(0, None)] * (2 * n),
        method="highs",
    )
    if not result.success:
        raise RuntimeError(f"quantile-regression LP failed: {result.message}")

    coefficients = result.x[:5]
    return {
        "coef": dict(
            zip(
                ("intercept", "black", "hispanic", "male", "ever_jailed"),
                coefficients.tolist(),
            )
        ),
        "n": n,
    }


def main() -> None:
    data = Path(__file__).parent / "data" / "nls_incarceration_processed.csv"
    df = pd.read_csv(data)
    print(json.dumps({str(q): fit_wealth_quantile(df, q) for q in (0.1, 0.5, 0.9)}, indent=2))


if __name__ == "__main__":
    main()

